CREATE TABLE IF NOT EXISTS shard_refs(name TEXT PRIMARY KEY,room TEXT NOT NULL,heads TEXT NOT NULL,root TEXT);
CREATE TABLE IF NOT EXISTS shard_batches(seq INTEGER PRIMARY KEY,room TEXT NOT NULL,id TEXT NOT NULL,parents TEXT NOT NULL,root TEXT,body TEXT NOT NULL,UNIQUE(room,id));
CREATE TABLE IF NOT EXISTS shard_versions(room TEXT NOT NULL,frontier TEXT NOT NULL,root TEXT,PRIMARY KEY(room,frontier));
CREATE TABLE IF NOT EXISTS shard_receipts(branch TEXT NOT NULL,request_id TEXT NOT NULL,input TEXT NOT NULL,result TEXT NOT NULL,PRIMARY KEY(branch,request_id));
CREATE TABLE IF NOT EXISTS shard_batch_files(room TEXT NOT NULL,file_id TEXT NOT NULL,batch TEXT NOT NULL,PRIMARY KEY(room,file_id,batch));
CREATE TABLE IF NOT EXISTS shard_nodes(hash TEXT PRIMARY KEY,body TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS shard_changes(seq INTEGER PRIMARY KEY,room TEXT NOT NULL,doc TEXT NOT NULL,hash TEXT NOT NULL,deps TEXT NOT NULL,body BLOB NOT NULL,UNIQUE(room,doc,hash));
CREATE TABLE IF NOT EXISTS shard_doc_stats(room TEXT NOT NULL,doc TEXT NOT NULL,changes_count INTEGER NOT NULL,bytes INTEGER NOT NULL,checkpoint_count INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(room,doc));
CREATE TABLE IF NOT EXISTS shard_checkpoints(seq INTEGER PRIMARY KEY,room TEXT NOT NULL,doc TEXT NOT NULL,heads TEXT NOT NULL,body BLOB NOT NULL,checksum TEXT NOT NULL,UNIQUE(room,doc,heads));
